def variants(S):
    pts=list(S); out=[]
    for k3 in range(4):
        # rotate 90: (r,c)->(c, -r) then normalize
        pts=[(c,-r) for r,c in pts]; mr=min(p[0] for p in pts); mc=min(p[1] for p in pts)
        pts=[(r-mr,c-mc) for r,c in pts]
        out.append(set(pts))
    v=list(out)
    for s3 in list(v):
        out.append({(-r,c) for r,c in s3} if False else {(r,-c) for r,c in s3})
    # normalize all
    res=[]
    for s3 in out:
        mr=min(p[0] for p in s3); mc=min(p[1] for p in s3)
        res.append({(r-mr,c-mc) for r,c in s3})
    # dedupe
