    sr, sc = seeds[0]
    shape = [(r - sr, c - sc) for r, c in seeds]
    out = g.copy()
    for a in range(h):
        for b in range(w):
            if all(0 <= a+dr < h and 0 <= b+dc < w and g[a+dr][b+dc] == bg for dr, dc in shape):
                for dr, dc in shape:
                    out[a+dr][b+dc] = seed_color
    return out.tolist()
